const ODOO = { url: ($env.ODOO_URL || 'http://odoo:8069') + '/jsonrpc', db: $env.ODOO_DB || 'hdx',
  login: $env.ODOO_N8N_LOGIN || 'n8n', pw: $env.ODOO_N8N_PASSWORD || '' };
if (!ODOO.pw) throw new Error('Thiếu ODOO_N8N_PASSWORD trong .env');
// Gọi JSON-RPC của Odoo, ném lỗi kèm thông báo của Odoo
const rpc = async (service, method, args) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: ODOO.url, json: true, timeout: 30000,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } } });
  if (r.error) throw new Error(`Odoo: ${(r.error.data && r.error.data.message) || r.error.message}`);
  return r.result;
};
const uid = await rpc('common', 'login', [ODOO.db, ODOO.login, ODOO.pw]);
if (!uid) throw new Error('Odoo: sai ODOO_N8N_LOGIN hoặc ODOO_N8N_PASSWORD');
// Gọi một method của model Odoo
const call = (model, method, args, kw = {}) => rpc('object', 'execute_kw', [ODOO.db, uid, ODOO.pw, model, method, args, kw]);

const e = $input.first().json;
const orderId = String((e.data || {}).order_id || e.order_id || '');
if (!orderId) throw new Error('Sự kiện không có data.order_id');
const so = (await call('sale.order', 'search_read', [[['client_order_ref', '=', orderId]]],
  { fields: ['name', 'state', 'picking_ids', 'order_line'], limit: 1 }))[0];
if (!so) return [{ json: { tiktok_order_id: orderId, cancelled: false, note: 'Odoo không có Sales Order cho đơn này', seller_skus: [] } }];
const lines = await call('sale.order.line', 'read', [so.order_line], { fields: ['product_id'] });
const prods = await call('product.product', 'read', [[...new Set(lines.map((l) => l.product_id[0]))]], { fields: ['default_code'] });
const skus = prods.map((p) => p.default_code).filter(Boolean);
if (so.state === 'cancel') return [{ json: { tiktok_order_id: orderId, odoo_sale_order: so.name, cancelled: false, note: 'đã hủy từ trước', seller_skus: skus } }];
const picks = so.picking_ids.length ? await call('stock.picking', 'read', [so.picking_ids], { fields: ['name', 'state'] }) : [];
const done = picks.filter((p) => p.state === 'done');
if (done.length) throw new Error(`Đơn ${orderId} (${so.name}) đã xuất kho ${done.map((p) => p.name).join(', ')}: không hủy tự động, nhận hàng hoàn về kho bằng tay`);
await call('sale.order', 'action_cancel', [[so.id]], { context: { disable_cancel_warning: true } });
const after = (await call('sale.order', 'read', [[so.id]], { fields: ['state'] }))[0];
if (after.state !== 'cancel') throw new Error(`Hủy ${so.name} không thành công, trạng thái vẫn là ${after.state}`);
return [{ json: { tiktok_order_id: orderId, odoo_sale_order: so.name, cancelled: true, seller_skus: skus } }];

